typedef enum { EV_ORDER_PLACED, EV_ADDRESS_CHANGED } ev_kind_t;
typedef struct {
    ev_kind_t kind; uint64_t ts;                        /* tag written first on the wire */
    union { struct { uint32_t order_id; } order_placed;
            struct { uint32_t customer_id; } address_changed; } u;
} event_msg_t;
void publish(const event_msg_t *e);                     /* enqueue for all subscribers */
size_t event_encode(const event_msg_t *e, uint8_t *buf, size_t cap);
/* subscriber */
event_msg_t e;
if (event_decode(buf, n, &e) && e.kind == EV_ORDER_PLACED)
    on_order_placed(e.u.order_placed.order_id);
